from scipy.optimize import least_squares
import warnings; warnings.filterwarnings('ignore')
y=dA_dt; v=np.var(y)
fams={
 'F1': (lambda p: p[0]*np.exp(-p[1]*t**2)+p[2]*A**p[3]*np.exp(-p[4]*t)+p[5]*A**p[6]*np.exp(-p[7]*t**2), 8),
 'F4': (lambda p: p[0]*np.exp(-p[1]*t**2)+p[2]*A**p[3]*np.exp(-p[4]*A*t)+p[5]*t**2+p[6]*A, 7),
}
rng=np.random.default_rng(1)
for name,(f,n) in fams.items():
    best=np.inf;bp=None
    for s in range(12):
        p0=rng.uniform(0.2,1.5,n)
        try:
            r=least_squares(lambda p: np.nan_to_num(f(p)-y,nan=1e6,posinf=1e6,neginf=-1e6), p0, max_nfev=300)
            m=np.mean(r.fun**2)/v
            if m<best: best=m;bp=r.x
        except Exception as e: pass
    print(name, best, np.round(bp,3), flush=True)

